{"cmd": "$proc = Start-Process -FilePath java -ArgumentList '-jar','build\libs\app.jar' -WorkingDirectory $PWD -WindowStyle Hidden -PassThru
try {
    $up = $false
    for ($i = 0; $i -lt 30; $i++) {
        Start-Sleep -Seconds 1
        try { $h = Invoke-RestMethod -Uri http://localhost:8080/actuator/health -TimeoutSec 2; if ($h.status -eq 'UP') { $up = $true; break } } catch {}
    }
    Write-Output "health up: $up"
    $ok = Invoke-RestMethod -Uri http://localhost:8080/api/bindings -Method Post -ContentType 'application/json' -Body '{"requestId":"DEMO-RQ-1","taskId":1001,"calibrationId":1001}'
    Write-Output "bind ok: $($ok | ConvertTo-Json -Compress)"
    try {
        Invoke-RestMethod -Uri http://localhost:8080/api/bindings -Method Post -ContentType 'application/json' -Body '{"requestId":"DEMO-RQ-2","taskId":1002,"calibrationId":1001}'
    } catch {
        $resp = $_.Exception.Response
        $reader = New-Object System.IO.StreamReader($resp.GetResponseStream())
        Write-Output "late task: HTTP $([int]$resp.StatusCode) $($reader.ReadToEnd())"
    }
    $chain = Invoke-RestMethod -Uri http://localhost:8080/api/antennas/ANT-01/calibration-chain
    Write-Output "chain: $($chain | ConvertTo-Json -Compress -Depth 6)"
} finally {
    Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue
    Write-Output "app stopped"
}", "yield_time_ms": 60000}

